+/// A 24-byte hex session token from the OS-seeded `RandomState` (no extra deps).
+pub fn make_token() -> String {
+    let mut s = String::with_capacity(48);
+    for i in 0..3u64 {
+        let mut h = RandomState::new().build_hasher();
+        h.write_u64(i);
+        s.push_str(&format!("{:016x}", h.finish()));
+    }
